async fn ontogen_document_related_get(
    State(ontogen_state): State<Arc<AppState>>,
    _: AcceptGuard,
    Path((id, rel)): Path<(LookupKey, LookupKey)>,
    RawQuery(ontogen_raw_query): RawQuery,
) -> Result<Response, ErrorObject> {
    let ontogen_collection = "/api/documents";
    match rel.as_str() {
        Some("match") => {
            QueryParams::parse(ontogen_raw_query.as_deref(), &QuerySpec::NONE)?;
            let ontogen_entity = ontogen_document_read(&ontogen_state, &id).await?;
            let ontogen_related = ontogen_doc_fetch(&ontogen_state, ontogen_entity.match_id.as_slice()).await?;
            let ontogen_data =
                ontogen_related.first().map(|ontogen_member| doc_as_resource(ontogen_member, "/api/docs"));
            let ontogen_self = format!("{ontogen_collection}/{}/match", encode_path_segment(&ontogen_entity.id));
            Ok(response::ok(&Document::new(ontogen_data, Links::new(ontogen_self))))
        }
        Some("ref") => {
            QueryParams::parse(ontogen_raw_query.as_deref(), &QuerySpec::NONE)?;
            let ontogen_entity = ontogen_document_read(&ontogen_state, &id).await?;
            let ontogen_related = ontogen_map_fetch(&ontogen_state, ontogen_entity.ref_id.as_slice()).await?;
            let ontogen_data =
                ontogen_related.first().map(|ontogen_member| map_as_resource(ontogen_member, "/api/maps"));
            let ontogen_self = format!("{ontogen_collection}/{}/ref", encode_path_segment(&ontogen_entity.id));
            Ok(response::ok(&Document::new(ontogen_data, Links::new(ontogen_self))))
        }
        Some("loop") => {
            QueryParams::parse(ontogen_raw_query.as_deref(), &QuerySpec::NONE)?;
            let ontogen_entity = ontogen_document_read(&ontogen_state, &id).await?;
            let ontogen_related = ontogen_response_fetch(&ontogen_state, &ontogen_entity.r#loop).await?;
            let ontogen_data: Vec<_> =
                ontogen_related.iter().map(|ontogen_member| response_as_resource(ontogen_member, "/api/responses")).collect();
            let ontogen_self = format!("{ontogen_collection}/{}/loop", encode_path_segment(&ontogen_entity.id));
            Ok(response::ok(&Document::new(ontogen_data, Links::new(ontogen_self))))
        }
        _ => Err(relationship_not_found("documents", &rel)),
    }
}

