            let ontogen_entity = ontogen_map_read(&ontogen_state, &id).await?;
            if let Some(ontogen_ids) = ontogen_removed(&ontogen_entity.children, &ontogen_linked) {
                ontogen_map_write_field(&ontogen_state, &ontogen_entity.id, "children", ontogen_ids.into()).await?;
            }
