async fn ontogen_map_related_get(
    State(ontogen_state): State<Arc<AppState>>,
    _: AcceptGuard,
    Path((id, rel)): Path<(LookupKey, LookupKey)>,
    RawQuery(ontogen_raw_query): RawQuery,
) -> Result<Response, ErrorObject> {
    let ontogen_collection = "/api/maps";
    match rel.as_str() {
        Some("in") => {
            QueryParams::parse(ontogen_raw_query.as_deref(), &QuerySpec::NONE)?;
            let ontogen_entity = ontogen_map_read(&ontogen_state, &id).await?;
            let ontogen_related = ontogen_map_fetch(&ontogen_state, ontogen_entity.r#in.as_slice()).await?;
            let ontogen_data =
                ontogen_related.first().map(|ontogen_member| map_as_resource(ontogen_member, "/api/maps"));
            let ontogen_self = format!("{ontogen_collection}/{}/in", encode_path_segment(&ontogen_entity.id));
            Ok(response::ok(&Document::new(ontogen_data, Links::new(ontogen_self))))
        }
        Some("children") => {
            QueryParams::parse(ontogen_raw_query.as_deref(), &QuerySpec::NONE)?;
            let ontogen_entity = ontogen_map_read(&ontogen_state, &id).await?;
            let ontogen_related = ontogen_map_fetch(&ontogen_state, &ontogen_entity.children).await?;
            let ontogen_data: Vec<_> =
                ontogen_related.iter().map(|ontogen_member| map_as_resource(ontogen_member, "/api/maps")).collect();
            let ontogen_self = format!("{ontogen_collection}/{}/children", encode_path_segment(&ontogen_entity.id));
            Ok(response::ok(&Document::new(ontogen_data, Links::new(ontogen_self))))
        }
        _ => Err(relationship_not_found("maps", &rel)),
    }
}

