async fn lookup_find_docs(
    State(ontogen_state): State<Arc<AppState>>,
    _: AcceptGuard,
    ontogen_query: Result<Query<NoParams>, ErrorObject>,
    ontogen_body: Body,
) -> Result<Response, ErrorObject> {
    ontogen_query?;
    let ontogen_bytes = ontogen_body.into_bytes()?;
    let ontogen_args = request::op_args(&ontogen_bytes, false)?;
    request::check_op_arg_names(&ontogen_args, &["r#type", "r#in", "class", "_kind"])?;
    let r#type = request::op_arg::<Option<String>>(&ontogen_args, "r#type", false)?;
    let r#in = request::op_arg::<Option<String>>(&ontogen_args, "r#in", false)?;
    let class = request::op_arg::<Option<String>>(&ontogen_args, "class", false)?;
    let _kind = request::op_arg::<Option<String>>(&ontogen_args, "_kind", false)?;
    let ontogen_store = ontogen_state.store().await.map_err(ontogen_internal_error)?;
    let ontogen_result = lookup::find_docs(&ontogen_store, r#type, r#in, class, _kind).await.map_err(ontogen_app_error)?;
    Ok(response::ok(&Document::meta_only(ResultMeta { result: ontogen_result })))
}

